<?php
class CompraDAO {
 public function __construct(private PDO $pdo){}
 public function listar(?int $usuarioId=null): array { $sql="SELECT c.*,u.nome,u.email,(SELECT COUNT(*) FROM compra_itens i WHERE i.compra_id=c.id) itens FROM compras c JOIN usuarios u ON u.id=c.usuario_id";if($usuarioId){$sql.=" WHERE c.usuario_id=? ORDER BY c.data_compra DESC";$s=$this->pdo->prepare($sql);$s->execute([$usuarioId]);return $s->fetchAll();}return $this->pdo->query($sql." ORDER BY c.data_compra DESC")->fetchAll(); }
 public function buscarPorId(int $id): ?array { $s=$this->pdo->prepare("SELECT c.*,u.nome,u.email FROM compras c JOIN usuarios u ON u.id=c.usuario_id WHERE c.id=?");$s->execute([$id]);$c=$s->fetch();if(!$c)return null;$i=$this->pdo->prepare("SELECT * FROM compra_itens WHERE compra_id=?");$i->execute([$id]);$c['itens']=$i->fetchAll();return $c; }
 public function finalizar(int $usuarioId,array $carrinho): int { if(!$carrinho)throw new RuntimeException('Seu carrinho está vazio.');$this->pdo->beginTransaction();try{$total=0;$itens=[];foreach($carrinho as $id=>$q){$s=$this->pdo->prepare("SELECT * FROM livros WHERE id=? AND ativo=1 FOR UPDATE");$s->execute([(int)$id]);$l=$s->fetch();$q=(int)$q;if(!$l||$q<1||(int)$l['estoque_venda']<$q)throw new RuntimeException('Estoque insuficiente para '.($l['titulo']??'um dos livros').'.');$sub=(float)$l['preco_venda']*$q;$total+=$sub;$itens[]=[$l,$q,$sub];} $s=$this->pdo->prepare("INSERT INTO compras(usuario_id,total,status) VALUES(?,?,'confirmado')");$s->execute([$usuarioId,$total]);$id=(int)$this->pdo->lastInsertId();foreach($itens as [$l,$q,$sub]){$this->pdo->prepare("INSERT INTO compra_itens(compra_id,livro_id,titulo_snapshot,preco_unitario,quantidade,subtotal) VALUES(?,?,?,?,?,?)")->execute([$id,$l['id'],$l['titulo'],$l['preco_venda'],$q,$sub]);$this->pdo->prepare("UPDATE livros SET estoque_venda=estoque_venda-? WHERE id=?")->execute([$q,$l['id']]);}$this->pdo->commit();return $id;}catch(Throwable $e){$this->pdo->rollBack();throw $e;} }
 public function editar(int $id,array $d): bool { $s=$this->pdo->prepare("SELECT status FROM compras WHERE id=?");$s->execute([$id]);$atual=$s->fetchColumn();if($atual===false||$atual==='cancelado')return false;if(($d['status']??'')==='cancelado')return $this->deletar($id);$status=in_array($d['status']??'', ['confirmado','separando','concluido'],true)?$d['status']:'confirmado';return $this->pdo->prepare("UPDATE compras SET status=? WHERE id=? AND status<>'cancelado'")->execute([$status,$id]); }
 public function deletar(int $id): bool { $this->pdo->beginTransaction();try{$s=$this->pdo->prepare("SELECT status FROM compras WHERE id=? FOR UPDATE");$s->execute([$id]);$c=$s->fetch();if(!$c){$this->pdo->commit();return false;}if($c['status']!=='cancelado'){$i=$this->pdo->prepare("SELECT livro_id,quantidade FROM compra_itens WHERE compra_id=? AND livro_id IS NOT NULL");$i->execute([$id]);foreach($i->fetchAll() as $item){$this->pdo->prepare("UPDATE livros SET estoque_venda=estoque_venda+? WHERE id=?")->execute([$item['quantidade'],$item['livro_id']]);}$this->pdo->prepare("UPDATE compras SET status='cancelado' WHERE id=?")->execute([$id]);}$this->pdo->commit();return true;}catch(Throwable $e){$this->pdo->rollBack();throw $e;} }
}
